#!/usr/bin/env php
<?php

declare(strict_types=1);

/**
 * Migrate Sail Friday users into the sailConnect auth service.
 *
 * For every user that is not yet linked (users.auth_user_id IS NULL) this creates the shared identity
 * (names and mobile number from the crew / boat-owner profile, bcrypt hash and created_at carried over,
 * display name generated by auth) and stores the new ID in users.auth_user_id. Safe to re-run.
 *
 * Run this BEFORE the migration 20261021120000_move_identity_to_auth, which drops the columns read here (and 20261021160000, which removes users.id)
 * (that migration also copies any mobile numbers of already-linked users into auth).
 *
 * Usage:
 *   php bin/migrate-users-to-auth.php                       # dry run: report only
 *   php bin/migrate-users-to-auth.php --apply               # write changes
 *   php bin/migrate-users-to-auth.php --apply --platform-admin=a@x.org,b@x.org
 *   Options: --db=/path/sailFriday.db  --auth-dir=/path/to/auth
 *
 * Back up both databases before using --apply.
 */

use SailConnect\Auth\Config;
use SailConnect\Auth\Database;
use SailConnect\Auth\UserRepository;
use SailConnect\Auth\Validator;

$projectRoot = dirname(__DIR__);
require_once $projectRoot . '/vendor/autoload.php';

$opt = getopt('', ['apply', 'db:', 'auth-dir:', 'platform-admin:']);
$apply = isset($opt['apply']);
$dbPath = $opt['db'] ?? $projectRoot . '/database/sailFriday.db';
$authDir = $opt['auth-dir'] ?? dirname($projectRoot) . '/auth';
$platformAdmins = array_filter(array_map(
    static fn (string $e): string => strtolower(trim($e)),
    explode(',', (string)($opt['platform-admin'] ?? ''))
));

$local = new PDO('sqlite:' . $dbPath, null, null, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
$local->exec('PRAGMA foreign_keys = ON');
$authConfig = Config::load($authDir);
$authDb = Database::connect($authConfig->dbPath());
$authUsers = new UserRepository($authDb);

$rows = $local->query("
    SELECT u.id, u.email, u.password_hash, u.account_type, u.created_at,
           c.first_name AS c_first, c.last_name AS c_last, c.membership_number AS c_member, c.mobile AS c_mobile,
           b.owner_first_name AS b_first, b.owner_last_name AS b_last, b.owner_mobile AS b_mobile
    FROM users u
    LEFT JOIN crews c ON c.user_id = u.id
    LEFT JOIN boats b ON b.owner_user_id = u.id
    WHERE u.auth_user_id IS NULL
    ORDER BY u.created_at, u.id
")->fetchAll();

$stats = ['migrated' => 0, 'linked_existing' => 0, 'skipped' => 0, 'platform_admins' => 0];
$issues = [];
$link = $local->prepare('UPDATE users SET auth_user_id = :a WHERE id = :id');

foreach ($rows as $r) {
    $email = strtolower(trim($r['email']));
    $first = trim((string)($r['c_first'] ?? $r['b_first'] ?? ''));
    $last = trim((string)($r['c_last'] ?? $r['b_last'] ?? ''));
    $member = trim((string)($r['c_member'] ?? ''));
    $mobile = trim((string)($r['c_mobile'] ?? '')) ?: trim((string)($r['b_mobile'] ?? ''));

    if (!Validator::email($email) || !Validator::name($first) || !Validator::name($last)) {
        $issues[] = "SKIPPED user {$r['id']} <{$r['email']}>: missing or invalid email/first/last name";
        $stats['skipped']++;
        continue;
    }

    $isMember = $member !== '' && Validator::membershipNumber($member);
    if ($member !== '' && !$isMember) {
        $issues[] = "user {$r['id']} <{$email}>: membership number \"{$member}\" is not a valid format; migrated as non-member";
    }

    $existing = $authUsers->findByEmail($email);
    if ($existing) {
        $issues[] = "user {$r['id']} <{$email}>: auth account already exists; linked to it";
        $stats['linked_existing']++;
        if ($apply) {
            $link->execute(['a' => $existing['user_id'], 'id' => $r['id']]);
        }
        continue;
    }

    $makeAdmin = in_array($email, $platformAdmins, true);
    $stats['platform_admins'] += $makeAdmin ? 1 : 0;

    if ($apply) {
        $created = $authUsers->create([
            'first_name' => $first,
            'last_name' => $last,
            'email_address' => $email,
            'password_hash' => $r['password_hash'],
            'is_member' => $isMember,
            'membership_number' => $isMember ? $member : null,
            'mobile_number' => $mobile,
            'is_platform_admin' => $makeAdmin,
            'created_at' => $r['created_at'] ?: Database::now(),
        ]);
        $link->execute(['a' => $created['user_id'], 'id' => $r['id']]);
        echo sprintf("  %-40s -> %s (%s)\n", $email, $created['display_name'], $created['user_id']);
    }
    $stats['migrated']++;
}

foreach ($platformAdmins as $e) {
    if (!$authUsers->findByEmail($e) && !array_filter($rows, static fn ($r) => strtolower(trim($r['email'])) === $e)) {
        $issues[] = "--platform-admin {$e}: no such user";
    }
}

echo ($apply ? "APPLIED" : "DRY RUN (no changes written; use --apply)") . "\n";
foreach ($stats as $k => $v) {
    echo sprintf("  %-16s %d\n", $k, $v);
}
if ($issues) {
    echo "\nNeeds attention:\n";
    foreach ($issues as $i) {
        echo "  - $i\n";
    }
}
exit($stats['skipped'] > 0 ? 2 : 0);
